ALTER TABLE public.agent_routines ADD COLUMN interval_minutes integer;
ALTER TABLE public.agent_routines ADD CONSTRAINT agent_routines_minutes_check CHECK (interval_minutes IS NULL OR interval_minutes BETWEEN 5 AND 10080);
CREATE OR REPLACE FUNCTION public.validate_agent_routine_owner() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.conversations WHERE id=NEW.conversation_id AND user_id=NEW.user_id) THEN RAISE EXCEPTION 'Conversation must belong to routine owner'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_agent_routine_owner BEFORE INSERT OR UPDATE ON public.agent_routines FOR EACH ROW EXECUTE FUNCTION public.validate_agent_routine_owner();
CREATE TABLE public.agent_browser_contexts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, bot_id uuid NOT NULL REFERENCES public.bots(id) ON DELETE CASCADE UNIQUE, context_id text, project_id text, lease_token uuid, lease_until timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.agent_browser_contexts TO service_role;
REVOKE ALL ON public.agent_browser_contexts FROM anon,authenticated;
ALTER TABLE public.agent_browser_contexts ENABLE ROW LEVEL SECURITY;
CREATE TRIGGER touch_agent_browser_contexts BEFORE UPDATE ON public.agent_browser_contexts FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE OR REPLACE FUNCTION public.claim_agent_browser(p_user uuid,p_bot uuid,p_token uuid) RETURNS SETOF public.agent_browser_contexts LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.bots WHERE id=p_bot AND owner_id=p_user) THEN RAISE EXCEPTION 'Bot unavailable'; END IF; INSERT INTO public.agent_browser_contexts(user_id,bot_id) VALUES(p_user,p_bot) ON CONFLICT(bot_id) DO NOTHING; RETURN QUERY UPDATE public.agent_browser_contexts SET lease_token=p_token,lease_until=now()+interval '12 minutes' WHERE bot_id=p_bot AND user_id=p_user AND (lease_until IS NULL OR lease_until<now()) RETURNING *; END $$;
REVOKE ALL ON FUNCTION public.claim_agent_browser(uuid,uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.claim_agent_browser(uuid,uuid,uuid) TO service_role;
CREATE TABLE public.agent_artifacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,name text NOT NULL,mime text NOT NULL,storage_path text NOT NULL UNIQUE,size_bytes integer NOT NULL CHECK(size_bytes BETWEEN 1 AND 20971520),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,DELETE ON public.agent_artifacts TO authenticated;
GRANT ALL ON public.agent_artifacts TO service_role;
ALTER TABLE public.agent_artifacts ENABLE ROW LEVEL SECURITY;
CREATE POLICY artifacts_read ON public.agent_artifacts FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY artifacts_delete ON public.agent_artifacts FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE TRIGGER touch_agent_artifacts BEFORE UPDATE ON public.agent_artifacts FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();